function isExactRequestedSlotAvailable(slotsArray: string[], requestedTime?: string): boolean {
  const normalized = normalizeRequestedTime(requestedTime || "");
  if (!normalized) return false;
  for (const slot of slotsArray) {
    const iso = parseSlotIso(slot);
    if (!iso) continue;
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) continue;
    const t = d.toLocaleTimeString("sv-SE", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Stockholm" });
    if (t === normalized) return true;
  }
  return false;
}

function getExactSlotIso(slotsArray: string[], requestedTime?: string): string | null {
  const normalized = normalizeRequestedTime(requestedTime || "");
  for (const slot of slotsArray) {
    const iso = parseSlotIso(slot);
    if (!iso) continue;
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) continue;
    const t = d.toLocaleTimeString("sv-SE", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Stockholm" });
    if (!normalized || t === normalized) return iso;
  }
  return null;
}

const explicitNamedBookingMonths: Record<string, number> = {
  january: 1, januari: 1, januar: 1, enero: 1, ژانویه: 1, يناير: 1,
  february: 2, februari: 2, februar: 2, febrero: 2, فوریه: 2, فبراير: 2,
  march: 3, mars: 3, märz: 3, maerz: 3, marzo: 3, مارس: 3,
  april: 4, abril: 4, آوریل: 4, أبريل: 4, إبريل: 4, ابريل: 4,
  may: 5, maj: 5, mai: 5, mayo: 5, مه: 5, مايو: 5,
  june: 6, juni: 6, junio: 6, ژوئن: 6, يونيو: 6,
  july: 7, juli: 7, julio: 7, ژوئیه: 7, يوليو: 7,
  august: 8, augusti: 8, agosto: 8, اوت: 8, أغسطس: 8, اغسطس: 8,
  september: 9, septiembre: 9, سپتامبر: 9, سبتمبر: 9,
  october: 10, oktober: 10, octubre: 10, اکتبر: 10, أكتوبر: 10, اكتوبر: 10,
  november: 11, noviembre: 11, نوامبر: 11, نوفمبر: 11,
  december: 12, dezember: 12, diciembre: 12, دسامبر: 12, ديسمبر: 12,
};
const explicitNamedBookingMonthPattern = Object.keys(explicitNamedBookingMonths)
  .sort((left, right) => right.length - left.length)
  .map((value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
  .join("|");

function parseExplicitNamedBookingDateParts(text: string): { day: number; month: number; year?: number } | null {
  const raw = normalizeConversationText(text).toLowerCase();
  const dayFirst = raw.match(new RegExp(
    `(?:^|\\s)(\\d{1,2})(?::[ae]|\\.|st|nd|rd|th)?\\s+(?:de\\s+)?(${explicitNamedBookingMonthPattern})(?:\\s+(?:de\\s+)?(20\\d{2}))?(?=\\s|[.!?,;]|$)`,
    "iu",
  ));
  if (dayFirst) {
    return {
      day: Number(dayFirst[1]),
      month: explicitNamedBookingMonths[dayFirst[2].toLowerCase()],
      ...(dayFirst[3] ? { year: Number(dayFirst[3]) } : {}),
    };
  }
  const monthFirst = raw.match(new RegExp(
    `(?:^|\\s)(${explicitNamedBookingMonthPattern})\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(20\\d{2}))?(?=\\s|[.!?,;]|$)`,
    "iu",
  ));
  if (!monthFirst) return null;
  return {
    day: Number(monthFirst[2]),
    month: explicitNamedBookingMonths[monthFirst[1].toLowerCase()],
    ...(monthFirst[3] ? { year: Number(monthFirst[3]) } : {}),
  };
}



function resolveExplicitBookingDate(text?: string): string | null {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ")
    .replace(/[،,!?؟;؛()[\]{}]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!raw) return null;

  if (getBookingDateConflict(raw, "Europe/Stockholm")) return null;

  const sharedExplicitDate = parseBookingDate(raw, "Europe/Stockholm");
  if (sharedExplicitDate?.kind === "exact_date" && sharedExplicitDate.value) {
    return sharedExplicitDate.value;
  }

  const today = stockholmDateString(new Date());

  const iso = raw.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;

  // A written calendar date is authoritative even when the same message also
  // contains a weekday, for example "onsdag 22 juli" or "22 juli, inte nästa onsdag".
  const namedDate = parseExplicitNamedBookingDateParts(raw);
  if (namedDate) {
    const year = namedDate.year || Number(today.slice(0, 4));
    const month = namedDate.month;
    const day = namedDate.day;
    const check = new Date(Date.UTC(year, month - 1, day));
    if (check.getUTCFullYear() === year && check.getUTCMonth() === month - 1 && check.getUTCDate() === day) {
      return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    }
    return null;
  }

  const numeric = raw.match(/\b(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](20\d{2}))?\b/);
  if (numeric) {
    const year = Number(numeric[3] || new Intl.DateTimeFormat("en", {
      timeZone: "Europe/Stockholm",
      year: "numeric"
    }).format(new Date()));
    return `${year}-${String(Number(numeric[2])).padStart(2, "0")}-${String(Number(numeric[1])).padStart(2, "0")}`;
  }

  // Reuse canonical forward-looking relative-date and weekday normalization so
  // multilingual booking continuations cannot diverge from availability parsing.
  const sharedDate = parseBookingDate(raw, "Europe/Stockholm");
  if (sharedDate?.value) return sharedDate.value;

  // Relative dates must still be resolved before weekday parsing. This is critical for
  // rescheduling messages such as "imorgon kl 18:30" and "farda saate 18:30".
  if (/\b(idag|today|heute|hoy|emruz|emrooz)\b/i.test(raw) || /(?:امروز|اليوم)/u.test(raw)) return today;
  if (
    /\b(igår|igar|yesterday|gestern|ayer|dirooz|diruz)\b/i.test(raw) ||
    /(?:دیروز|أمس|امس)/u.test(raw)
  ) {
    return addDaysToStockholmDate(today, -1);
  }
  // Check day-after-tomorrow BEFORE tomorrow. Otherwise "pas farda" also matches "farda".
  if (/\b(i\s*övermorgon|övermorgon|day after tomorrow|pas\s*farda|pasfarda|پس\s*فردا|پسفردا)\b/i.test(raw)) {
    return addDaysToStockholmDate(today, 2);
  }
  if (/\b(i\s*morgon|imorgon|tomorrow|farda|فردا)\b/i.test(raw)) {
    return addDaysToStockholmDate(today, 1);
  }

  // Persian weekday numbers are weekday names, not calendar day numbers. Match all
  // compound forms before bare "shanbe" so "3 shanbe" can never degrade to Saturday.
  const weekdayMap: Array<[RegExp, number]> = [
    [/(?:^|\s)(?:söndag|sunday|sonntag|domingo|الأحد|الاحد|yek\s*shanbe|yekshanbe|1\s*shanbe|یک\s*شنبه)(?=\s|$)/iu, 0],
    [/(?:^|\s)(?:måndag|mandag|monday|montag|lunes|الاثنين|الإثنين|do\s*shanbe|doshanbe|2\s*shanbe|دو\s*شنبه)(?=\s|$)/iu, 1],
    [/(?:^|\s)(?:tisdag|tuesday|dienstag|martes|الثلاثاء|se\s*shanbe|seshanbe|3\s*shanbe|سه\s*شنبه)(?=\s|$)/iu, 2],
    [/(?:^|\s)(?:onsdag|wednesday|mittwoch|miércoles|miercoles|الأربعاء|الاربعاء|chahar\s*shanbe|chaharshanbe|4\s*shanbe|چهار\s*شنبه|چهارشنبه)(?=\s|$)/iu, 3],
    [/(?:^|\s)(?:torsdag|thursday|donnerstag|jueves|الخميس|panj\s*shanbe|panjshanbe|5\s*shanbe|پنج\s*شنبه|پنجشنبه)(?=\s|$)/iu, 4],
    [/(?:^|\s)(?:fredag|friday|freitag|viernes|الجمعة|jome|jomeh|جمعه)(?=\s|$)/iu, 5],
    [/(?:^|\s)(?:lördag|lordag|saturday|samstag|sábado|sabado|السبت|shanbe|شنبه)(?=\s|$)/iu, 6]
  ];

  const matched = weekdayMap.find(([pattern]) => pattern.test(raw));
  if (!matched) return null;

  const targetDay = matched[1];
  const todayStr = stockholmDateString(new Date());
  const [year, month, day] = todayStr.split("-").map(Number);
  const todayUtc = new Date(Date.UTC(year, month - 1, day));
  const currentDay = todayUtc.getUTCDay();

  let daysAhead = (targetDay - currentDay + 7) % 7;
  const explicitlyThisWeek = /\bthis\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i.test(raw) ||
    /(?:همین|این)\s*(?:شنبه|یک\s*شنبه|دو\s*شنبه|سه\s*شنبه|چهار\s*شنبه|پنج\s*شنبه|جمعه)/u.test(raw);
  if (daysAhead === 0 && !explicitlyThisWeek && !/\b(idag|today|امروز)\b/i.test(raw)) daysAhead = 7;

  // "next week / hafte ayande" is an explicit week qualifier. A plain "next Tuesday"
  // remains the next upcoming Tuesday, while "Tuesday next week" moves into next week.
  const explicitlyNextWeek = /\bnext\s+week\b|\bhafte\s+ayande\b|هفته\s+آینده/u.test(raw);
  if (explicitlyNextWeek && daysAhead < 7) daysAhead += 7;

  todayUtc.setUTCDate(todayUtc.getUTCDate() + daysAhead);
  return todayUtc.toISOString().slice(0, 10);
}

type AvailabilityRangeRequest = {
  startDate: string;
  endDate: string;
  minTime?: string;
  maxTime?: string;
  flexibleDays: boolean;
};

function getConfiguredBookingWindowDays(config: any): number {
  const value = Number(
    config?.bookingWindowDays ??
    config?.booking_window_days ??
    config?.advanceBookingDays ??
    config?.advance_booking_days ??
    30
  );
  return Number.isFinite(value) ? Math.max(1, Math.min(365, Math.round(value))) : 30;
}

function extractRequestedWeekdays(text?: string): Array<{ index: number; position: number }> {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .toLowerCase()
    .replace(/\u200c/g, " ");
  const definitions: Array<[number, RegExp]> = [
    [0, /\b(?:söndag|sondag|sunday|sonntag|domingo|yek\s*shanbe|yekshanbe|1\s*shanbe)\b|یک\s*شنبه|الأحد|الاحد/giu],
    [1, /\b(?:måndag|mandag|monday|montag|lunes|do\s*shanbe|doshanbe|2\s*shanbe)\b|دو\s*شنبه|الاثنين|الإثنين/giu],
    [2, /\b(?:tisdag|tuesday|dienstag|martes|se\s*shanbe|seshanbe|3\s*shanbe)\b|سه\s*شنبه|الثلاثاء/giu],
    [3, /\b(?:onsdag|wednesday|mittwoch|miércoles|miercoles|chahar\s*shanbe|chaharshanbe|4\s*shanbe)\b|چهار\s*شنبه|چهارشنبه|الأربعاء|الاربعاء/giu],
    [4, /\b(?:torsdag|thursday|donnerstag|jueves|panj\s*shanbe|panjshanbe|5\s*shanbe)\b|پنج\s*شنبه|پنجشنبه|الخميس/giu],
    [5, /\b(?:fredag|friday|freitag|viernes|jome|jomeh)\b|جمعه|الجمعة/giu],
    [6, /\b(?:lördag|lordag|saturday|samstag|sábado|sabado|(?<!yek\s)(?<!do\s)(?<!se\s)(?<!chahar\s)(?<!panj\s)(?<![1-5]\s)shanbe)\b|(?<!یک\s)(?<!دو\s)(?<!سه\s)(?<!چهار\s)(?<!پنج\s)شنبه|السبت/giu]
  ];
  const matches: Array<{ index: number; position: number }> = [];
  for (const [index, pattern] of definitions) {
    for (const match of raw.matchAll(pattern)) {
      const position = Number(match.index || 0);
      if (!matches.some((item) => item.position === position)) matches.push({ index, position });
    }
  }
  return matches.sort((a, b) => a.position - b.position);
}

function normalizeWindowClock(hoursText: string, minutesText?: string): string | null {
  const hours = Number(hoursText);
  const minutes = Number(minutesText || 0);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes) || hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return null;
  }
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function extractAvailabilityTimeWindow(text?: string): {
  minTime: string;
  maxTime: string;
} | null {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ")
    .replace(/[–—]/g, "-");
  const timeRangePattern =
    /(?:mellan|between|from|från|fran|zwischen|von|entre|desde|بين|من|بین|از)?\s*(\d{1,2})(?::([0-5]\d))?\s*(?:-|till|to|and|och|å|bis|und|hasta|y|إلى|الى|و|تا)\s*(\d{1,2})(?::([0-5]\d))?(?:\s*(?:kl|klockan|uhr|ساعت|الساعة))?/giu;
  let selected: { minTime: string; maxTime: string } | null = null;
  for (const candidate of raw.matchAll(timeRangePattern)) {
    const minTime = normalizeWindowClock(candidate[1], candidate[2]);
    const maxTime = normalizeWindowClock(candidate[3], candidate[4]);
    if (
      minTime &&
      maxTime &&
      Number(timeTextToMinutes(maxTime)) > Number(timeTextToMinutes(minTime))
    ) {
      selected = { minTime, maxTime };
    }
  }
  return selected;
}

function isInclusiveForwardAvailabilityFromDateRequest(text?: string): boolean {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .normalize("NFKC")
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ");

  if (!raw) return false;

  return (
    /\b(?:eller\s+senare|eller\s+senare\s+datum)\b/iu.test(raw) ||
    /\b(?:or\s+later|or\s+after)\b/iu.test(raw) ||
    /\b(?:oder\s+später|oder\s+spaeter)\b/iu.test(raw) ||
    /\b(?:o\s+después|o\s+despues|o\s+más\s+tarde|o\s+mas\s+tarde)\b/iu.test(raw)
  );
}

function isForwardAvailabilityAfterDateRequest(text?: string): boolean {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .normalize("NFKC")
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ");

  if (!raw) return false;

  return (
    /\b(?:after|following)\s+(?:the\s+)?(?:date\s+)?(?:20\d{2}-\d{2}-\d{2}|\d{1,2}(?:st|nd|rd|th)?\s+(?:january|february|march|april|may|june|july|august|september|october|november|december)|(?:january|february|march|april|may|june|july|august|september|october|november|december)\s+\d{1,2}(?:st|nd|rd|th)?)/iu.test(raw) ||
    /\b(?:nearest|soonest|earliest|next)\s+(?:available\s+)?(?:time|slot|appointment)?\s*after\b/iu.test(raw) ||

    /\b(?:efter)\s+(?:den\s+)?(?:\d{1,2})(?:\s+[a-zåäö]+)?/iu.test(raw) ||
    /\b(?:närmast|tidigast|första\s+lediga|nästa\s+lediga)\s+efter\b/iu.test(raw) ||

    /\b(?:nach)\s+(?:dem\s+)?(?:\d{1,2})(?:\s+(?:januar|februar|märz|maerz|april|mai|juni|juli|august|september|oktober|november|dezember))\b/iu.test(raw) ||
    /\b(?:después|despues)\s+(?:del?\s+)?(?:\d{1,2})(?:\s+de\s+[a-záéíóúñ]+)?/iu.test(raw) ||

    /(?:بعد\s+از|پس\s+از)\s*(?:تاریخ\s*)?[\d۰-۹٠-٩]+/u.test(raw) ||
    /(?:بعد|بعد\s+من)\s*(?:تاريخ\s*)?[\d٠-٩۰-۹]+/u.test(raw)
  );
}

function parseAvailabilityRangeRequest(
  text: string,
  businessConfig: any,
  now: Date = new Date()
): AvailabilityRangeRequest | null {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ")
    .replace(/[–—]/g, "-");
  if (!raw) return null;

  const namedDateRange = parseNamedBookingDateRange(
    raw,
    String(businessConfig?.timezone || "Europe/Stockholm"),
    now
  );
  // Bare day numbers in a named calendar range are dates, not a clock window.
  const timeWindow = namedDateRange ? null : extractAvailabilityTimeWindow(raw);
  const minTime = timeWindow?.minTime || null;
  const maxTime = timeWindow?.maxTime || null;
  const hasValidWindow = Boolean(timeWindow);

  const flexibleDays = /\b(det\s+spelar\s+ingen\s+roll\s+vilken\s+dag|vilken\s+dag\s+som\s+helst|any\s+day|doesn'?t\s+matter\s+which\s+day|jeder\s+tag|welcher\s+tag\s+ist\s+egal|cualquier\s+d[ií]a|no\s+importa\s+qu[eé]\s+d[ií]a|farghi\s+nadare\s+che\s+roozi)\b/i.test(raw) ||
    /هر\s*روز|فرقی\s*نداره\s*چه\s*روزی|أي\s*يوم|لا\s*يهم\s*أي\s*يوم/u.test(raw);
  const weekdays = extractRequestedWeekdays(raw);
  const hasRangeConnector = /\b(till|through|until|to|och|and)\b|(?:^|\s)å(?:\s|$)|تا|و/u.test(raw);

  let explicitStartDate: string | null = null;
  let explicitEndDate: string | null = null;
  const isValidDate = (value: string) => {
    const parsed = new Date(`${value}T12:00:00Z`);
    return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
  };
  const isoRange = raw.match(/\b(20\d{2}-\d{2}-\d{2})\s*(?:till|to|through|–|-)\s*(20\d{2}-\d{2}-\d{2})\b/i);
  if (isoRange && isValidDate(isoRange[1]) && isValidDate(isoRange[2]) && isoRange[1] <= isoRange[2]) {
    explicitStartDate = isoRange[1];
    explicitEndDate = isoRange[2];
  }
  if (!explicitStartDate && namedDateRange) {
    explicitStartDate = namedDateRange.startDate;
    explicitEndDate = namedDateRange.endDate;
  }
  if (!explicitStartDate) {
    const sharedExplicitDate = parseBookingDate(
      raw,
      String(businessConfig?.timezone || "Europe/Stockholm"),
      now
    );
    if (sharedExplicitDate?.kind === "exact_date" && sharedExplicitDate.value) {
      explicitStartDate = sharedExplicitDate.value;
      explicitEndDate = sharedExplicitDate.value;
    }
  }
  if (!explicitStartDate) {
    const numericRange = raw.match(/\b(\d{1,2})[/.](\d{1,2})\s*(?:till|to|through|–|-)\s*(\d{1,2})[/.](\d{1,2})(?:[/.](20\d{2}))?\b/i);
    if (numericRange) {
      const year = Number(numericRange[5] || stockholmDateString(new Date()).slice(0, 4));
      const start = `${year}-${String(Number(numericRange[2])).padStart(2, "0")}-${String(Number(numericRange[1])).padStart(2, "0")}`;
      const end = `${year}-${String(Number(numericRange[4])).padStart(2, "0")}-${String(Number(numericRange[3])).padStart(2, "0")}`;
      if (isValidDate(start) && isValidDate(end) && start <= end) {
        explicitStartDate = start;
        explicitEndDate = end;
      }
    }
  }

  if (!flexibleDays && !explicitStartDate && weekdays.length === 0) return null;
  if (!hasValidWindow && !weekdays.length && !explicitStartDate) return null;

  const businessTimezone = String(businessConfig?.timezone || "Europe/Stockholm");
  const today = getDateInTimeZone(now, businessTimezone);
  if (flexibleDays) {
    return {
      startDate: today,
      endDate: addDaysToStockholmDate(today, getConfiguredBookingWindowDays(businessConfig)),
      ...(hasValidWindow ? { minTime: minTime!, maxTime: maxTime! } : {}),
      flexibleDays: true
    };
  }

  if (explicitStartDate && explicitEndDate) {
    if (
      explicitStartDate === explicitEndDate &&
      isInclusiveForwardAvailabilityFromDateRequest(raw)
    ) {
      return {
        startDate: explicitStartDate,
        endDate: addDaysToStockholmDate(
          explicitStartDate,
          getConfiguredBookingWindowDays(businessConfig)
        ),
        ...(hasValidWindow ? { minTime: minTime!, maxTime: maxTime! } : {}),
        flexibleDays: false
      };
    }

    if (
      explicitStartDate === explicitEndDate &&
      isForwardAvailabilityAfterDateRequest(raw)
    ) {
      const forwardStartDate = addDaysToStockholmDate(
        explicitStartDate,
        1
      );

      return {
        startDate: forwardStartDate,
        endDate: addDaysToStockholmDate(
          forwardStartDate,
          getConfiguredBookingWindowDays(businessConfig)
        ),
        ...(hasValidWindow ? { minTime: minTime!, maxTime: maxTime! } : {}),
        flexibleDays: false
      };
    }

    return {
      startDate: explicitStartDate,
      endDate: explicitEndDate,
      ...(hasValidWindow ? { minTime: minTime!, maxTime: maxTime! } : {}),
      flexibleDays: false
    };
  }

  const startDate = parseBookingDate(raw, businessTimezone, now)?.value || today;
  let endDate = startDate;
  if (weekdays.length >= 2 && hasRangeConnector) {
    const [year, month, day] = startDate.split("-").map(Number);
    const startUtc = new Date(Date.UTC(year, month - 1, day));
    const daysToEnd = (weekdays[1].index - weekdays[0].index + 7) % 7;
    startUtc.setUTCDate(startUtc.getUTCDate() + (daysToEnd || 7));
    endDate = startUtc.toISOString().slice(0, 10);
  }

  return {
    startDate,
    endDate,
    ...(hasValidWindow ? { minTime: minTime!, maxTime: maxTime! } : {}),
    flexibleDays: false
  };
}

function isWholeDayAvailabilityRequest(text?: string): boolean {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .trim()
    .toLowerCase()
    .replace(/\u200c/g, " ")
    .replace(/[،,!?؟;؛.]+/g, " ")
    .replace(/\s+/g, " ");
  if (!raw) return false;
  return (
    /\b(?:any\s+time|anytime|any\s+time\s+that\s+day|all\s+day|whole\s+day|only\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)|do\s+you\s+have\s+any\s+time)\b/i.test(raw) ||
    /\b(?:vilken\s+tid\s+som\s+helst|n[aå]gon\s+tid|hela\s+dagen|bara\s+(?:p[aå]\s+)?(?:m[aå]ndag|tisdag|onsdag|torsdag|fredag|l[oö]rdag|s[oö]ndag)|har\s+du\s+(?:inte\s+)?(?:n[aå]gon\s+)?tid)\b/i.test(raw) ||
    /\b(?:irgendeine\s+uhrzeit|jederzeit|den\s+ganzen\s+tag|nur\s+(?:am\s+)?(?:montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag))\b/i.test(raw) ||
    /\b(?:cualquier\s+hora|a\s+cualquier\s+hora|todo\s+el\s+d[ií]a|solo\s+(?:el\s+)?(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo))\b/i.test(raw) ||
    /\b(?:har\s+saati|har\s+vaght|tamame?\s+rooz|faghat\s+(?:shanbe|yekshanbe|doshanbe|seshanbe|chaharshanbe|panjshanbe|jomeh?))\b/i.test(raw) ||
    /(?:هر\s*(?:ساعت|وقتی)|تمام\s*روز|فقط\s*(?:شنبه|یک\s*شنبه|دو\s*شنبه|سه\s*شنبه|چهار\s*شنبه|پنج\s*شنبه|جمعه)|أي\s*وقت|طوال\s*اليوم|فقط\s*(?:الأحد|الاحد|الاثنين|الإثنين|الثلاثاء|الأربعاء|الاربعاء|الخميس|الجمعة|السبت))/u.test(raw)
  );
}

function isAvailabilityPivotFromFailedLookup(text?: string): boolean {
  if (!resolveExplicitBookingDate(text)) return false;
  const raw = normalizeConfirmationReply(text);
  return (
    isWholeDayAvailabilityRequest(text) ||
    isNewBookingRequestText(text) ||
    /\b(?:what\s+about|how\s+about|do\s+you\s+have|available|ledig|ledigt|vad\s+s[aä]gs\s+om|wie\s+w[aä]re\s+es|hast\s+du\s+zeit|qu[eé]\s+tal|tienes\s+hora|chetor(?:e)?|vaght\s+dari)\b/iu.test(raw) ||
    /(?:وقت\s+داری|زمان\s+خالی|چه(?:طور|‌طور)\s+است|ماذا\s+عن|هل\s+لديك\s+وقت|موعد\s+متاح)/u.test(String(text || ""))
  );
}

function getAvailabilityDateComponent(
  text: string,
  businessConfig: any,
  fallbackDate?: string | null
): {
  detected: boolean;
  kind: "weekday" | "explicit_date" | "date_range" | "inherited" | null;
  resolvedDate: string | null;
  endDate: string | null;
  weekday: string | null;
} {
  const weekdayNames = [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday"
  ];
  const weekdays = extractRequestedWeekdays(text);
  const range = parseAvailabilityRangeRequest(text, businessConfig);
  const explicitDate = resolveExplicitBookingDate(text);
  if (weekdays.length > 0) {
    return {
      detected: true,
      kind: weekdays.length > 1 && range?.startDate !== range?.endDate
        ? "date_range"
        : "weekday",
      resolvedDate: range?.startDate || explicitDate,
      endDate: range?.endDate || explicitDate,
      weekday: weekdayNames[weekdays[0].index] || null
    };
  }
  if (range) {
    return {
      detected: true,
      kind: range.startDate === range.endDate ? "explicit_date" : "date_range",
      resolvedDate: range.startDate,
      endDate: range.endDate,
      weekday: null
    };
  }
  if (explicitDate) {
    return {
      detected: true,
      kind: "explicit_date",
      resolvedDate: explicitDate,
      endDate: explicitDate,
      weekday: null
    };
  }
  return {
    detected: false,
    kind: fallbackDate ? "inherited" : null,
    resolvedDate: fallbackDate || null,
    endDate: fallbackDate || null,
    weekday: null
  };
}

function availabilityTimeRelation(boundary?: TimeBoundary | null): string | null {
  if (!boundary) return null;
  if (boundary.kind === "exclusive_lower") return "after";
  if (boundary.kind === "inclusive_lower") return "from";
  if (boundary.kind === "exclusive_upper") return "before";
  if (boundary.kind === "inclusive_upper") return "until";
  return "around";
}

function deriveCanonicalAvailabilityConstraint(
  text: string,
  businessConfig: any,
  previous?: CanonicalAvailabilityConstraint | null,
  normalized?: NormalizedBookingRequest,
  latestTime?: NormalizedTimeConstraint,
  now: Date = new Date()
): CanonicalAvailabilityConstraint | null {
  const timezone = String(businessConfig?.timezone || "Europe/Stockholm");
  if (getBookingDateConflict(text, timezone, now)) return null;
  const parsedRange = parseAvailabilityRangeRequest(
    text,
    businessConfig,
    now
  );
  const hasMultiDayRange = Boolean(parsedRange && parsedRange.startDate !== parsedRange.endDate);
  const sharedDate = !hasMultiDayRange
    ? normalized?.date || parseBookingDate(
        text,
        timezone,
        now
      )
    : undefined;
  const range = sharedDate ? null : parsedRange;
  const explicitDate = sharedDate?.value || resolveExplicitBookingDate(text);
  const authoritativeTime = latestTime || (!normalized ? parseTimeConstraint(text) : undefined);
  const latestTurnHasExplicitAvailabilityDate =
    Boolean(parsedRange || parseBookingDate(text, timezone, now)?.value);

  const retainedTime =
    authoritativeTime || latestTurnHasExplicitAvailabilityDate
      ? undefined
      : normalized?.timeConstraint;

  const namedCalendarDateRange = parseNamedBookingDateRange(
    text,
    timezone,
    now
  );
  const timeWindow = authoritativeTime || namedCalendarDateRange
    ? null
    : extractAvailabilityTimeWindow(text);
  const timeFollowUp = parseRescheduleTimeFollowUp(text);
  const daypart = inferRequestedDaypart(text);
  const broadensToWholeDay = isWholeDayAvailabilityRequest(text);
  const dateComponent = sharedDate ? { detected: true, kind: sharedDate.kind === "weekday" ? "weekday" as const : "explicit_date" as const, resolvedDate: sharedDate.value || null, endDate: sharedDate.value || null, weekday: sharedDate.weekday === undefined ? null : ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"][sharedDate.weekday] } : getAvailabilityDateComponent(text, businessConfig, previous?.startDate);
  const hasDateSignal = Boolean(range || explicitDate);
  const refersToSameDay = /\b(?:that\s+day|same\s+day|den\s+dagen|samma\s+dag|diesem\s+tag|gleichen\s+tag|ese\s+d[ií]a|mismo\s+d[ií]a|hamoon\s+rooz|hamon\s+rooz)\b/i.test(text) ||
    /(?:همون|همان)\s*روز|ذلك\s*اليوم|نفس\s*اليوم/u.test(text);

  // A time-only refinement belongs to the currently owned availability range.
  // Inherit only its date(s); every time constraint is rebuilt from this turn.
  const refinesActiveDate = Boolean(
    previous &&
    (
      timeWindow ||
      timeFollowUp.boundary ||
      timeFollowUp.explicitTime ||
      daypart
    )
  );
  const weekdayReference = getBookingWeekdayReference(text);
  const retainsRepeatedBareWeekday = Boolean(
    previous &&
    previous.startDate === previous.endDate &&
    sharedDate?.kind === 'weekday' &&
    weekdayReference?.qualifier === 'bare' &&
    !isAlternativeAvailabilityRequest(text) &&
    new Date(`${previous.startDate}T12:00:00Z`).getUTCDay() === weekdayReference.weekday
  );
  const inheritPreviousDate =
    refersToSameDay ||
    broadensToWholeDay ||
    refinesActiveDate;
  const startDate =
    (retainsRepeatedBareWeekday ? previous?.startDate : sharedDate?.value) ||
    range?.startDate ||
    explicitDate ||
    (inheritPreviousDate ? previous?.startDate : undefined);
  const endDate =
    (retainsRepeatedBareWeekday ? previous?.endDate : sharedDate?.value) ||
    range?.endDate ||
    explicitDate ||
    (inheritPreviousDate ? previous?.endDate : undefined);
  if (!startDate || !endDate) return null;
  const todayInBusinessTimezone = getDateInTimeZone(now, timezone);
  if (startDate < todayInBusinessTimezone || endDate < todayInBusinessTimezone) return null;

  const common = {
    startDate,
    endDate,
    dateComponentKind: dateComponent.detected
      ? dateComponent.kind || undefined
      : "inherited" as const,
    ...(dateComponent.weekday ? { weekday: dateComponent.weekday } : {}),
    rejectedTimes: Array.from(new Set([
      ...(refersToSameDay && !timeFollowUp.explicitTime
        ? previous?.rejectedTimes || []
        : []),
      ...timeFollowUp.rejectedTimes,
    ])),
    generatedFromLatestRequestAt: Date.now(),
    timezone: String(businessConfig?.timezone || "Europe/Stockholm"),
    ...(isEarliestAvailabilityRequest(text) ? { selectFirstAvailable: true } : {})
  };

  // The latest turn's normalized time constraint is authoritative. It must be
  // applied before any merged prior constraint or text fallback can reconstruct
  // an incompatible range/daypart/boundary from pending state.
  if (authoritativeTime) {
    return {
      ...common,
      ...availabilityFieldsFromConstraint(authoritativeTime)
    } as CanonicalAvailabilityConstraint;
  }

  // A date/weekday-only follow-up inside an active availability flow is a fresh
  // whole-day request. It must not inherit a rejected exact time or old bounds.
  if (
    broadensToWholeDay ||
    (
      hasDateSignal &&
      !timeWindow &&
      !timeFollowUp.explicitTime &&
      !timeFollowUp.boundary &&
      !daypart && !retainedTime
    )
  ) {
    return { ...common, kind: startDate === endDate ? "whole_day" : "date_range", rejectedTimes: [] };
  }
  if (timeWindow) {
    return {
      ...common,
      kind: "time_window",
      minTime: timeWindow.minTime,
      maxTime: timeWindow.maxTime
    };
  }
  if (timeFollowUp.boundary) {
    if (timeFollowUp.boundary.kind === "approximate") {
      return {
        ...common,
        kind: "approximate_time",
        exactTime: timeFollowUp.boundary.time,
        timeBoundary: timeFollowUp.boundary
      };
    }
    return {
      ...common,
      kind: "time_boundary",
      timeBoundary: timeFollowUp.boundary
    };
  }
  if (timeFollowUp.explicitTime) {
    return {
      ...common,
      kind: "exact_time",
      exactTime: timeFollowUp.explicitTime
    };
  }
  if (daypart) {
    const daypartOptions = getDaypartSlotOptions(daypart);
    return {
      ...common,
      kind: "daypart",
      daypart,
      minTime: daypartOptions.minTime,
      maxTime: daypartOptions.maxTime
    };
  }
  if (retainedTime && retainedTime.kind !== "none") {
    return { ...common, ...availabilityFieldsFromConstraint(retainedTime) } as CanonicalAvailabilityConstraint;
  }
  if (refersToSameDay) {
    return {
      ...common,
      kind: startDate === endDate ? "whole_day" : "date_range",
    };
  }
  return range
    ? { ...common, kind: startDate === endDate ? "whole_day" : "date_range", rejectedTimes: [] }
    : null;
}

function availabilityConstraintSlotOptions(
  constraint: CanonicalAvailabilityConstraint
): SlotSearchOptions {
  return {
    ...(constraint.minTime ? { minTime: constraint.minTime } : {}),
    ...(constraint.maxTime ? { maxTime: constraint.maxTime } : {}),
    ...(constraint.timeBoundary ? { timeBoundary: constraint.timeBoundary } : {}),
    ...(constraint.selectFirstAvailable ? { selectFirstAvailable: true } : {}),
    ...(Array.isArray(constraint.rejectedTimes) && constraint.rejectedTimes.length
      ? { excludedTimes: constraint.rejectedTimes }
      : {})
  };
}

function canonicalAvailabilityConstraintKey(
  constraint: CanonicalAvailabilityConstraint,
  context: { businessId: string; service: string; timezone: string; durationMinutes: number; time?: NormalizedTimeConstraint }
): string | null {
  return safeLogFingerprint(buildSlotFingerprintSource({ businessId: context.businessId, service: context.service, date: `${constraint.startDate}/${constraint.endDate}/${constraint.selectFirstAvailable ? "earliest" : "preferred"}`, timezone: context.timezone, constraint: context.time, durationMinutes: context.durationMinutes }));
}

function slotSatisfiesAvailabilityConstraint(
  startIso: string,
  constraint?: CanonicalAvailabilityConstraint | null
): boolean {
  if (!constraint) return true;
  const date = new Date(ensureStockholmOffset(String(startIso || "")));
  if (Number.isNaN(date.getTime())) return false;

  const zoned = getZonedSlotParts(startIso, constraint?.timezone || "Europe/Stockholm");
  const localDate = zoned?.date || "";
  const slotMinutes = zoned?.minutes ?? null;
  const localTime = slotMinutes === null ? null : `${String(Math.floor(slotMinutes / 60)).padStart(2, "0")}:${String(slotMinutes % 60).padStart(2, "0")}`;
  if (
    !localTime ||
    slotMinutes === null ||
    localDate < constraint.startDate ||
    localDate > constraint.endDate
  ) return false;

  if (
    constraint.kind === "exact_time" &&
    normalizeRequestedTime(constraint.exactTime || "") !== localTime
  ) return false;

  const minMinutes = timeTextToMinutes(constraint.minTime);
  const maxMinutes = timeTextToMinutes(constraint.maxTime);
  if (minMinutes !== null && slotMinutes < minMinutes) return false;
  if (maxMinutes !== null && slotMinutes > maxMinutes) return false;

  const boundaryMinutes = timeTextToMinutes(constraint.timeBoundary?.time);
  if (boundaryMinutes !== null) {
    if (
      constraint.timeBoundary?.kind === "exclusive_lower" &&
      slotMinutes <= boundaryMinutes
    ) return false;
    if (
      constraint.timeBoundary?.kind === "inclusive_lower" &&
      slotMinutes < boundaryMinutes
    ) return false;
    if (
      constraint.timeBoundary?.kind === "exclusive_upper" &&
      slotMinutes >= boundaryMinutes
    ) return false;
    if (
      constraint.timeBoundary?.kind === "inclusive_upper" &&
      slotMinutes > boundaryMinutes
    ) return false;
  }

  return !(constraint.rejectedTimes || []).some(
    (time) => normalizeRequestedTime(time) === localTime
  );
}

function isAlternativeAvailabilityRequest(text?: string): boolean {
  const raw = String(text || "").trim().toLowerCase();
  return /\b(?:other|another|alternative|different)\s+(?:available\s+)?(?:time|times|slot|slots|day|days|date|dates|availability|appointment|appointments|booking|bookings)\b/iu.test(raw) ||
    /\b(?:andra|alternativa|någon annan dag|andra dagar|outside|utanför|dagar efter|roo?z(?:e|hay)? dige|روز(?:های)? دیگر)\b/iu.test(raw);
}

function isPendingSelectionRejectionRequest(text: string, pending: any): boolean {
  if (
    !pending?.dateTime ||
    !["awaiting_confirmation", "awaiting_contact", "failed_recoverable"].includes(
      String(pending?.status || "")
    ) ||
    isCancellationIntent(text) ||
    isRescheduleIntent(text)
  ) return false;

  const followUp = parseRescheduleTimeFollowUp(text);
  const selectedTime = getStockholmTimeFromIso(String(pending.dateTime || ""));
  if (
    followUp.rejectsCurrentSelection &&
    (
      followUp.rejectedTimes.length === 0 ||
      !selectedTime ||
      followUp.rejectedTimes.includes(selectedTime)
    )
  ) return true;

  const raw = normalizeConfirmationReply(text);
  return (
    /\b(?:(?:no|not that)\s+)?(?:another|different|other)\s+(?:time|slot|appointment)\b/iu.test(raw) ||
    /\b(?:nej|inte den|annan|annat)\s+(?:tid|tiden|klockslag)\b/iu.test(raw) ||
    /\b(?:nein|nicht diese|andere)\s+(?:zeit|uhrzeit|termin)\b/iu.test(raw) ||
    /\b(?:no esa|otra|diferente)\s+(?:hora|cita)\b/iu.test(raw) ||
    /(?:نه|اون\s*وقت\s*نه|آن\s*وقت\s*نه|وقت\s*(?:دیگه|دیگر)|زمان\s*(?:دیگه|دیگر))/u.test(raw) ||
    /(?:لا|ليس هذا الموعد|موعد آخر|وقت آخر)/u.test(raw)
  );
}

function isEarliestAvailabilityRequest(text?: string): boolean {
  const raw = normalizeLocalizedDigits(String(text || ""))
    .normalize("NFKC")
    .trim()
    .toLowerCase();
  if (!raw) return false;
  return (
    /\b(?:earliest|first\s+available|soonest|next\s+available|first\s+(?:free|open)\s+(?:time|slot|appointment))\b/iu.test(raw) ||
    /\b(?:tidigaste|första\s+lediga|närmast\s+lediga|nästa\s+lediga|närmast\s+efter|så\s+snart\s+som\s+möjligt|så\s+tidigt\s+som\s+möjligt)\b/iu.test(raw) ||
    /\b(?:as\s+soon\s+as\s+possible|nearest\s+after|soonest\s+after|earliest\s+after)\b/iu.test(raw) ||
    /\b(?:früheste|erste\s+freie|nächste\s+freie)\b/iu.test(raw) ||
    /\b(?:más\s+tempran[oa]|primera\s+(?:hora|cita)\s+disponible|próxima\s+(?:hora|cita)\s+disponible)\b/iu.test(raw) ||
    /(?:زودترین|اولین\s+(?:وقت|زمان)\s+(?:خالی|آزاد)|نزدیکترین\s+وقت)/u.test(raw) ||
    /(?:أقرب\s+موعد|أول\s+موعد\s+متاح|أبكر\s+موعد)/u.test(raw)
  );
}

function formatRangeAvailabilityReply(
  slots: string[],
  language: string,
  request: AvailabilityRangeRequest,
  outsideOriginalRange: boolean,
  toneConfig?: unknown,
): string {
  if (slots.length === 0) {
    if (language === "sv") return `Jag hittar inga lediga tider mellan ${request.minTime || "öppning"} och ${request.maxTime || "stängning"} i det önskade intervallet. Vill du att jag söker andra dagar?`;
    if (language === "fa") return `در بازه درخواستی بین ${request.minTime || "زمان باز شدن"} تا ${request.maxTime || "زمان بسته شدن"} وقت خالی پیدا نکردم. روزهای دیگری را بررسی کنم؟`;
    if (language === "de") return `Im gewünschten Zeitraum finde ich zwischen ${request.minTime || "Öffnung"} und ${request.maxTime || "Schließung"} keinen freien Termin. Soll ich andere Tage prüfen?`;
    if (language === "es") return `No encuentro horas libres entre ${request.minTime || "la apertura"} y ${request.maxTime || "el cierre"} en el intervalo solicitado. ¿Busco otros días?`;
    if (language === "ar") return `لم أجد مواعيد متاحة بين ${request.minTime || "الافتتاح"} و${request.maxTime || "الإغلاق"} ضمن النطاق المطلوب. هل أبحث في أيام أخرى؟`;
    return `I can’t find an available time between ${request.minTime || "opening"} and ${request.maxTime || "closing"} in the requested range. Shall I check other days?`;
  }

  const base = buildLocalizedSlotReply(slots, undefined, language, toneConfig);
  if (!outsideOriginalRange) return base;
  if (language === "sv") return `Utanför det ursprungliga intervallet hittade jag: ${base}`;
  if (language === "fa") return `خارج از بازه اولیه این زمان‌ها خالی هستند: ${base}`;
  if (language === "de") return `Außerhalb des ursprünglichen Zeitraums habe ich Folgendes gefunden: ${base}`;
  if (language === "es") return `Fuera del intervalo original encontré: ${base}`;
  if (language === "ar") return `خارج النطاق الأصلي وجدت: ${base}`;
  return `Outside the original requested range, I found: ${base}`;
}

function formatSlotNoLongerAvailable(
  language: string,
  selectedTime: string | undefined,
  alternatives: string[],
  toneConfig?: unknown,
): string {
  const time = normalizeRequestedTime(selectedTime || "") || selectedTime || "";
  const alternativeText = alternatives.length > 0
    ? buildLocalizedSlotReply(alternatives, undefined, language, toneConfig)
    : "";
  if (language === "sv") {
    return alternatives.length > 0
      ? `Tiden kl. ${time} hann tyvärr bli upptagen. ${alternativeText}`
      : `Tiden kl. ${time} hann tyvärr bli upptagen. Jag hittar ingen annan ledig tid den dagen just nu.`;
  }
  if (language === "fa") {
    return alternatives.length > 0
      ? `متأسفانه ساعت ${time} دیگر خالی نیست. ${alternativeText}`
      : `متأسفانه ساعت ${time} دیگر خالی نیست و فعلاً زمان آزاد دیگری در همان روز پیدا نکردم.`;
  }
  if (language === "de") {
    return alternatives.length > 0
      ? `Der Termin um ${time} Uhr wurde leider gerade vergeben. ${alternativeText}`
      : `Der Termin um ${time} Uhr wurde leider gerade vergeben. Aktuell finde ich an diesem Tag keine weitere freie Zeit.`;
  }
  if (language === "es") {
    return alternatives.length > 0
      ? `La hora de las ${time} acaba de ocuparse. ${alternativeText}`
      : `La hora de las ${time} acaba de ocuparse y no encuentro otra libre ese día.`;
  }
  if (language === "ar") {
    return alternatives.length > 0
      ? `للأسف تم حجز موعد الساعة ${time} للتو. ${alternativeText}`
      : `للأسف تم حجز موعد الساعة ${time} للتو، ولا أجد وقتًا آخر متاحًا في ذلك اليوم.`;
  }
  return alternatives.length > 0
    ? `The ${time} slot was just taken. ${alternativeText}`
    : `The ${time} slot was just taken, and I can’t find another available time that day right now.`;
}

function resolveRescheduleDate(text: string, appointment?: any): string | null {
  const explicit = resolveExplicitBookingDate(text);
  if (explicit) return explicit;

  const raw = String(text || "").trim().toLowerCase();
  const appointmentStart = String(appointment?.start || "").trim();
  const appointmentDate = appointmentStart
    ? stockholmDateString(new Date(ensureStockholmOffset(appointmentStart)))
    : null;

  // "same day", "samma dag", and equivalent phrases refer to the current appointment date.
  if (
    appointmentDate &&
    /\b(samma dag|samma datum|den dagen|same day|same date|hamon rooz|hamoon rooz|همان روز|همون روز)\b/i.test(raw)
  ) {
    return appointmentDate;
  }

  // During an active reschedule flow, a reply containing only a new clock time means
  // keep the appointment date and change only the time. This prevents endless loops
  // after messages such as "imorgon kl 18:30" followed by "18:30" or "samma dag 18:30".
  if (appointmentDate && inferRequestedTimeFromText(raw)) return appointmentDate;

  return null;
}

function isRescheduleDateCorrection(text?: string): boolean {
  const raw = String(text || "").trim().toLowerCase();
  if (!raw) return false;
  const hasExplicitCalendarDate =
    /\b20\d{2}-\d{2}-\d{2}\b/.test(raw) ||
    /\b\d{1,2}[\/.\-]\d{1,2}(?:[\/.\-]20\d{2})?\b/.test(raw) ||
    /\b(?:den\s+)?\d{1,2}\s+(?:januari|februari|mars|april|maj|juni|juli|augusti|september|oktober|november|december)(?:\s+20\d{2})?\b/i.test(raw);
  if (!hasExplicitCalendarDate) return false;
  return /\b(nej|inte|menar|rättelse|istället|no|not|mean|instead)\b/i.test(raw);
}

function inferBookingDurationFromContext(text: string, history: any[]): number {
  const combined = [
    ...(history || []).slice(-10).map((item: any) =>
      typeof item?.content === "string" ? item.content : ""
    ),
    text || ""
  ].join(" ").toLowerCase();

  // Keep service recognition in one place. This also catches stretched or
  // misspelled Finglish such as "moshaveeeereh".
  if (inferServiceFromText(combined) === "Konsultation") return 30;

  const minuteMatch = combined.match(/(\d{1,3})\s*(?:min|minuter|minutes|دقیقه)/i);
  if (minuteMatch) {
    const value = Number(minuteMatch[1]);
    if (value >= 10 && value <= 240) return value;
  }

  return 60;
}

function isBookingConversationContext(text: string, history: any[]): boolean {
  if (isReadOnlyAvailabilityInquiry(text)) return true;
  const combined = [
    ...(history || []).slice(-10).map((item: any) =>
      typeof item?.content === "string" ? item.content : ""
    ),
    text || ""
  ].join(" ").toLowerCase();

  // A recognized service is enough to keep the message inside the deterministic
  // booking engine. Accept common Finglish endings such as "vaghte" as well.
  if (inferServiceFromText(combined) !== "Bokning") return true;

  return /\b(boka|bokning|tid(?:en)?|appointment|book|booking|vaght(?:e|i)?|begir(?:am|im)|رزرو|وقت)\b/i.test(combined);
}

function getSlotsArray(result: any): string[] {
  return String(result?.available_slots_string || "")
    .split("\n")
    .map((value) => value.trim())
    .filter((value) => value && !value.includes("No available slots"));
}

function findOfferedSlotIso(offeredSlots: string[], selectedTime?: string): string | null {
  const normalized = normalizeRequestedTime(selectedTime || "");
  if (!normalized) return null;

  for (const slot of offeredSlots || []) {
    const iso = parseSlotIso(slot);
    if (!iso) continue;
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) continue;
    const time = date.toLocaleTimeString("sv-SE", {
      timeZone: "Europe/Stockholm",
      hour: "2-digit",
      minute: "2-digit"
    });
    if (time === normalized) return iso;
  }
  return null;
}

function findOwnedOfferedSlot(pending: any, startIso?: string | null): OwnedOfferedSlot | null {
  const targetMs = new Date(ensureStockholmOffset(String(startIso || ""))).getTime();
  if (!Number.isFinite(targetMs)) return null;
  return (Array.isArray(pending?.ownedOfferedSlots) ? pending.ownedOfferedSlots : []).find(
    (slot: OwnedOfferedSlot) =>
      new Date(ensureStockholmOffset(String(slot?.start || ""))).getTime() === targetMs
  ) || null;
}

function selectOwnedOfferedSlot(text: string, pending: any): OwnedOfferedSlot | null {
  const explicitDate = resolveExplicitBookingDate(text);
  const selectedIso = selectRescheduleOfferedSlot(
    text,
    Array.isArray(pending?.offeredSlots) ? pending.offeredSlots : []
  );
  const selectedOwnedSlot = findOwnedOfferedSlot(pending, selectedIso);
  if (
    selectedOwnedSlot &&
    (
      !explicitDate ||
      stockholmDateString(
        new Date(ensureStockholmOffset(selectedOwnedSlot.start))
      ) === explicitDate
    )
  ) return selectedOwnedSlot;

  // A longer slot-selection turn can contain contact details after the clock
  // value. Resolve that explicit value only against already-owned offers and
  // fail closed unless it identifies exactly one offer.
  const explicitClockTimes = new Set(
    Array.from(normalizeLocalizedDigits(String(text || "")).matchAll(/(?:^|\s)([01]?\d|2[0-3])[\.:]([0-5]\d)(?=[^\d]|$)/g))
      .map((match) => `${String(Number(match[1])).padStart(2, "0")}:${match[2]}`)
  );
  if (explicitClockTimes.size === 0) return null;

  const matchingOwnedSlots = (Array.isArray(pending?.ownedOfferedSlots) ? pending.ownedOfferedSlots : [])
    .filter((slot: OwnedOfferedSlot) => {
      const start = new Date(ensureStockholmOffset(String(slot?.start || "")));
      if (Number.isNaN(start.getTime())) return false;
      if (
        explicitDate &&
        stockholmDateString(start) !== explicitDate
      ) return false;
      const localTime = start.toLocaleTimeString("sv-SE", {
        timeZone: "Europe/Stockholm",
        hour: "2-digit",
        minute: "2-digit"
      });
      return explicitClockTimes.has(localTime);
    });
  return matchingOwnedSlots.length === 1 ? matchingOwnedSlots[0] : null;
}

function selectUniqueOwnedOfferedSlotByTime(time: string, pending: any): OwnedOfferedSlot | null {
  const normalized = normalizeRequestedTime(time);
  if (!normalized) return null;
  const matching = (Array.isArray(pending?.ownedOfferedSlots) ? pending.ownedOfferedSlots : [])
    .filter((slot: OwnedOfferedSlot) => getStockholmTimeFromIso(String(slot?.start || "")) === normalized);
  return matching.length === 1 ? matching[0] : null;
}

function isExistingAppointmentLookupIntent(text?: string): boolean {
  const raw = String(text || "").trim().toLowerCase();
  if (!raw) return false;
  if (isDirectAppointmentLookupPhrase(raw)) return true;

  const lookupPatterns = [
    /\b(do i|did i|have i|can you check|check if i).*(appointment|booking|booked)\b/i,
    /\b(when is|what time is).*(appointment|booking)\b/i,
    /\b(jag har|har jag|kan du kolla|kan du kontrollera).*(tid|bokning|bokat)\b/i,
    /\b(har jag en tid|har jag bokat|när är min tid|när är min bokning)\b/i,
    /\b(aya|آیا|میشه|می‌شود|میتونی|می‌تونی|mitoni|mishe).*(vaght|وقت|رزرو|booking|boka).*(daram|دارم|kardam|کردم|ya na|یا نه)\b/i,
    /\b(nemidonam|نمی.?دونم|motmaen nistam|مطمئن نیستم).*(vaght|وقت|رزرو|booking|boka)\b/i,
    /\b(habe ich|kannst du prüfen|wann ist).*(termin|buchung)\b/i,
    /\b(tengo|puedes comprobar|cuándo es).*(cita|reserva)\b/i,
    /(?:هل لدي(?=\s|$)|هل حجزت|متى موعدي|تحقق من موعدي)/i
  ];

  return lookupPatterns.some((pattern) => pattern.test(raw));
}

function isExistingBookingOperationRecoveryIntent(text?: string): boolean {
  const raw = String(text || "").trim().toLowerCase().normalize("NFKC");
  if (!raw) return false;
  return /\b(i (?:already )?have (?:an? )?(?:appointment|booking)|i have already booking|but i (?:already )?have|i (?:only|just) want to (?:change|move|reschedule)|change my existing booking|my existing booking)\b/iu.test(raw) ||
    /\b(jag har redan (?:en )?(?:bokning|tid)|jag vill bara (?:ändra|flytta|boka om)|min befintliga bokning|ändra min bokning)\b/iu.test(raw) ||
    /(من قبلاً وقت دارم|من از قبل رزرو دارم|فقط می.?خوام وقتمو تغییر بدم|رزرو قبلی|وقت قبلی)/u.test(raw) ||
    /\b(man az ghabl vaght daram|man ghablan rezerv daram|faghat mikham vaghtam ro taghir bedam|hamoon booking ghabli)\b/iu.test(raw);
}

function isPastAppointmentLookupIntent(text?: string): boolean {
  const raw = String(text || "").trim().toLowerCase();
  if (!raw) return false;
  return /(?:^|\s)(igår|igar|yesterday|gestern|ayer|dirooz|diruz|tidigare|förra\s+veckan|last\s+week|letzte\s+woche|semana\s+pasada|hade\s+tid|had\s+an\s+appointment|hatte\s+ich\s+einen\s+termin|ten[ií]a\s+una\s+cita|missat|missed)(?=\s|$)/i.test(raw) ||
    /(?:دیروز|قرار قبلی|وقت قبلی|أمس|امس|موعد سابق)/u.test(raw);
}

function hasExplicitEntityBearingBookingConfirmation(text?: string): boolean {
  const raw = normalizeConfirmationReply(text);
  if (!raw || !/^(?:yes|yeah|yep|sure)\b/u.test(raw)) return false;
  if (!/\b(?:please\s+)?book\s+it\b/u.test(raw)) return false;
  return !/\b(?:no|not|dont|do not|maybe|perhaps|instead|change|different|another|cancel|reschedule)\b/u.test(raw);
}

function isSpanishSelectedSlotConfirmation(
  text: string,
  pending: any,
  normalizedRequest?: NormalizedBookingRequest,
): boolean {
  if (String(pending?.language || normalizedRequest?.language || "") !== "es") return false;

  const raw = normalizeConfirmationReply(text);
  if (!raw) return false;
  if (
    /(?:^|\s)(?:no|quizas|tal vez|quiza|puede que)(?:\s|$)/u.test(raw) ||
    /\b(?:cancelar|cancela|cancelala|anular|anula|cambiar|cambia|mover|mueve|reprogramar|reprograma)\b/u.test(raw)
  ) return false;

  const affirmativeOnly = /^si(?: por favor)?$/u.test(raw);
  const bookingAuthorization = /^(?:si(?: por favor)?\s+)?(?:(?:quiero\s+)?(?:reserva|reservar|reservala|reservarla|confirma|confirmar|confirmala))\b/u.test(raw);
  if (!affirmativeOnly && !bookingAuthorization) return false;

  const selectedSlots = (Array.isArray(pending?.ownedOfferedSlots) ? pending.ownedOfferedSlots : [])
    .filter((slot: OwnedOfferedSlot) =>
      new Date(ensureStockholmOffset(String(slot?.start || ""))).getTime() ===
        new Date(ensureStockholmOffset(String(pending?.dateTime || ""))).getTime() &&
      new Date(ensureStockholmOffset(String(slot?.end || ""))).getTime() ===
        new Date(ensureStockholmOffset(String(pending?.selectedSlotEnd || ""))).getTime()
    );
  if (selectedSlots.length !== 1) return false;

  const pendingSlot = getZonedSlotParts(
    String(pending.dateTime || ""),
    String(pending?.businessConfig?.timezone || "Europe/Stockholm"),
  );
  if (!pendingSlot) return false;

  if (normalizedRequest?.date?.value && normalizedRequest.date.value !== pendingSlot.date) return false;
  if (normalizedRequest?.dateConflict) return false;

  if (normalizedRequest?.timeConstraint) {
    if (
      normalizedRequest.timeConstraint.kind !== "exact" ||
      normalizedRequest.timeConstraint.startMinutes !== pendingSlot.minutes
    ) return false;
  }

  const configuredServiceMention = findConfiguredBookingService(text, pending?.businessConfig);
  if (
    configuredServiceMention &&
    normalizeBookingService(configuredServiceMention, configuredServiceMention) !==
      normalizeBookingService(pending?.service, pending?.service)
  ) return false;

  if (
    normalizedRequest?.service?.normalized &&
    normalizedRequest.service.normalized !== normalizeBookingService(pending?.service, pending?.service)
  ) return false;

  return true;
}

function isPendingSlotConfirmation(
  text: string | undefined,
  pending: any,
  normalizedRequest?: NormalizedBookingRequest,
): boolean {
  if (!pending || !["awaiting_confirmation", "awaiting_contact"].includes(String(pending.status || ""))) return false;

  const raw = String(text || "").trim();
  if (!raw) return false;

  if (isSpanishSelectedSlotConfirmation(raw, pending, normalizedRequest)) return true;
  const normalizedConfirmation = normalizeConfirmationReply(raw);
  const persianSelectedSlotAuthorization =
    /^(?:بله|اره|باشه)(?: لطفا)? رزرو (?:کنید|کن)(?:\s|$)/u.test(normalizedConfirmation) ||
    /^(?:لطفا )?رزرو (?:کنید|کن)$/u.test(normalizedConfirmation) ||
    /^(?:لطفا )?برایم ثبت (?:کنید|کن)$/u.test(normalizedConfirmation) ||
    /^(?:لطفا )?وقت (?:را|رو) رزرو (?:کنید|کن)$/u.test(normalizedConfirmation);
  if (persianSelectedSlotAuthorization) {
    const pendingSlot = getZonedSlotParts(
      String(pending.dateTime || ""),
      String(pending?.businessConfig?.timezone || "Europe/Stockholm"),
    );
    if (!pendingSlot || normalizedRequest?.dateConflict) return false;
    if (normalizedRequest?.date?.value && normalizedRequest.date.value !== pendingSlot.date) return false;
    if (
      normalizedRequest?.timeConstraint &&
      (
        normalizedRequest.timeConstraint.kind !== "exact" ||
        normalizedRequest.timeConstraint.startMinutes !== pendingSlot.minutes
      )
    ) return false;
    return true;
  }
  if (isAffirmativeBookingText(raw)) return true;
  if (hasExplicitEntityBearingBookingConfirmation(raw)) return true;

  const selectedTime = inferRequestedTimeFromText(raw);
  if (!selectedTime) return false;

  const pendingDate = new Date(ensureStockholmOffset(pending.dateTime));
  if (Number.isNaN(pendingDate.getTime())) return false;

  const pendingTime = pendingDate.toLocaleTimeString("sv-SE", {
    timeZone: "Europe/Stockholm",
    hour: "2-digit",
    minute: "2-digit"
  });

  if (selectedTime !== pendingTime) return false;

  // A customer repeating the offered time with normal confirmation wording
  // must count as confirmation, even without words such as "yes" or "ok".
  return /\b(khube|khob|good|works|fine|passar|bra|går bra|okej|ok|mitonam|yes|ja|vale|bien|gut)\b/i.test(raw) ||
    /(?:می.?تونم|خوبه|مناسبه|باشه|بله|آره)/u.test(raw)
    || raw.replace(/\s+/g, "") === selectedTime.replace(":", "");
}

function hasExplicitSelectedSlotBookingAuthorization(text?: string): boolean {
  const raw = normalizeConversationText(String(text || "")).toLowerCase();
  if (/\b(?:no|not|dont|do not|maybe|perhaps|instead|change|different|another|cancel|reschedule)\b/iu.test(raw)) {
    return false;
  }
  return /\b(?:(?:kan|skulle)\s+du\s+)?(?:gärna\s+)?(?:boka|reservera)\s+(?:den\s+tiden|tiden|den)\b/iu.test(raw) ||
    /\b(?:can|could|would)\s+you\s+(?:please\s+)?book\s+(?:it|that\s+one|that\s+slot|the\s+slot)\b/iu.test(raw) ||
    /\bplease\s+book\s+(?:it|that\s+one|that\s+slot|the\s+slot)\b/iu.test(raw);
}


